// Register a patient (full intake form)  (permissions: patient.create)
export const createPatient = (body) =>
  api("POST", `/patients`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Update demographics (optimistic locking)  (permissions: patient.update)
export const updatePatient = (patient_id, body) =>
  api("PATCH", `/patients/${patient_id}`, body);   // api(): see get_guide('envelope-and-errors')

// Register + OPD slip + payment + queue token (atomic)  (permissions: opd.ticket.create)
export const registerReceptionRegistrations = (body) =>
  api("POST", `/reception/registrations`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Patient profile (+ outstanding banner, merged profiles)  (permissions: patient.view)
export const getPatient = (patient_id) =>
  api("GET", `/patients/${patient_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Returning-patient lookup by name / phone / CNIC / UPMRN / MRN  (permissions: patient.search)
export const searchPatients = () =>
  api("GET", `/patients/search`, undefined);   // api(): see get_guide('envelope-and-errors')
